def parse_row(line: str) -> list[str]:
    """Parse a CSV row respecting double-quoted fields."""
    result = []
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            # Toggle quote state when encountering unescaped quotes (simple heuristic)
            if not in_quotes and char != '\\':
                in_quotes = True
            elif in_quotes and char == '"':
                in_quotes = False  # Handle escaped quotes by toggling off here too
        else:
            current_field += char

    result.append(current_field)

    return result
