import re

def parse_money(s: str) -> float | None:
    if not s or s.lower() in ("", "n/a"):
        return None

    # Strip leading/trailing whitespace and remove $ sign
    cleaned = s.strip().replace("$", "").strip()

    # Remove thousands separators (commas, spaces between groups)
    cleaned = re.sub(r"\s*,\s*", ",", cleaned)  # Handle "1,234" -> "1234"
    cleaned = re.sub(r"[ ,]+", "", cleaned)      # Also handle single commas/spaces

    try:
        return float(cleaned)
    except ValueError:
        return None
